import axios from "@/assets/api/axios.js";

const api = {
    getInfo: (params) => axios("get", "/role/getRoleInfo", params), // 获取角色属性
    postXlStatus: (params) => axios("postjson", "/role/postXlStatus", params), // 切换修炼状态
    postInfo: (params) => axios("postjson", "/role/postRoleInfo", params), // 保存角色属性

    postModifyRole: (params) => axios("postjson", "/postModifyRole", params), // 修改角色信息
    getRoleList: (params) => axios("get", "/role/getRoleList", params) // 获取所有角色列表
};
export default api;
